  test('validates correct metadata', () => {
    const metadata = {
      version: 'v1.0.0',
      customer: { id: 'cus_123', email: 'test@example.com' },
      order: {
        items: [{ id: 'item_1', name: 'Product', quantity: 1, price: 9.99 }],
        currency: 'USD',
        total: 9.99
      }
    };

    const result = validateTokenMetadata(metadata, VALID_SCHEMA);
    expect(result.isValid).toBe(true);
    expect(result.errors).toHaveLength(0);
  });

