        path: 'order',
        message: expect.stringContaining('required')
      })
    );
  });

  test('rejects invalid types', () => {
    const metadata = {
      version: 'v1.0.0',
      order: {
        items: 'not-an-array', // should be array
        currency: 'USD',
        total: 9.99
      }
    };
    const result = validateTokenMetadata(metadata, VALID_SCHEMA);
    expect(result.isValid).toBe(false);
    expect(result.errors).toContainEqual(
      expect.objectContaining({
        path: 'order.items',
        message: expect.stringContaining('array')
      })
    );
  });

  test('rejects invalid email format', () => {
    const metadata = {
      version: 'v1.0.0',
      customer: { id: 'cus_123', email: 'invalid-email' },
      order: {
        items: [{ id: 'item_1', name: 'Product', quantity: 1, price: 9.99 }],
        currency: 'USD',
        total: 9.99
      }
    };
    const result = validateTokenMetadata(metadata, VALID_SCHEMA);
    expect(result.isValid).toBe(false);
    expect(result.errors).toContainEqual(
      expect.objectContaining({
        path: 'customer.email',
        message: expect.stringContaining('email')
      })
    );
  });

  test('handles nested object validation', () => {
    const metadata = {
      version: 'v1.0.0',
      billing: {
        address: {
          city: 'San Francisco',
          country: 'US'
        }
      },
      order: {
        items: [{ id: 'item_1', name: 'Product', quantity: 1, price: 9.99 }],
        currency: 'USD',
        total: 9.99
      }
    };
    const result = validateTokenMetadata(metadata, VALID_SCHEMA);
    expect(result.isValid).toBe(true);
    expect(result.errors).toHaveLength(0);
  });

  test('rejects unknown properties at top level', () => {
    const metadata = {
      version: 'v1.0.0',
      order: {
        items: [{ id: 'item_1', name: 'Product', quantity: 1, price: 9.99 }],
        currency: 'USD',
        total: 9.99
      },
      unknown_field: 'value' // not allowed
    };
    const result = validateTokenMetadata(metadata, VALID_SCHEMA);
    expect(result.isValid).toBe(false);
    expect(result.errors).toContainEqual(
      expect.objectContaining({
        path: 'unknown_field',
        message: expect.stringContaining('additional')
      })
    );
  });

  test('handles explicit null values', () => {
