export class TokenizationService {
  async tokenize(paymentData: any): Promise<string> {
    // Extract metadata if present
    const metadata = paymentData.metadata as TokenMetadata | undefined;

    if (metadata) {
      // Validate metadata structure
      const validationResult = validateTokenMetadata(metadata, this.getSchema());

      if (!validationResult.isValid) {
        // Log validation errors (without sensitive data)
        console.warn('Metadata validation failed:', {
          errors: validationResult.errors,
          // Never log the actual metadata value for security
          metadataPresent: !!metadata
        });

        throw new Error(`Invalid metadata: ${validationResult.errors.map(e => e.message).join(', ')}`);
      }
    }

    // Process tokenization...
    return `tok_${Date.now()}`;
  }

