export const validateTokenMetadata = (metadata: any, schema: any): { isValid: boolean; errors: any[] } => {
  const errors: Array<{ path: string; message: string }> = [];

  function validateValue(value: any, currentSchema: any, path: string, isRequired: boolean = false): void {
    // If value is null or undefined
    if (value === null || value === undefined) {
      if (isRequired) {
        errors.push({
          path,
          message: `${path} is required`
        });
      }
      return;
    }

    // Type check
    if (currentSchema.type) {
      if (!checkType(value, currentSchema.type)) {
        errors.push({
          path,
          message: `${path} must be of type ${currentSchema.type}`
        });
        return;
