    if (currentSchema.type === 'string' || (typeof value === 'string')) {
      if (currentSchema.minLength !== undefined && value.length < currentSchema.minLength) {
        errors.push({
          path,
          message: `${path} must be at least ${currentSchema.minLength} characters long`
        });
      }
      if (currentSchema.pattern) {
        const regex = new RegExp(currentSchema.pattern);
        if (!regex.test(value)) {
          errors.push({
            path,
            message: `${path} does not match required pattern`
          });
        }
      }
      if (currentSchema.format === 'email') {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(value)) {
          errors.push({
            path,
            message: `${path} has invalid format`
          });
        }
      }
    }

    // Number validations
    if (currentSchema.type === 'number' || (typeof value === 'number')) {
      if (currentSchema.minimum !== undefined && value < currentSchema.minimum) {
        errors.push({
          path,
          message: `${path} must be at least ${currentSchema.minimum}`
        });
      }
    }

    // Array validations
    if (Array.isArray(value)) {
      if (currentSchema.minItems !== undefined && value.length < currentSchema.minItems) {
        errors.push({
          path,
          message: `${path} must have at least ${currentSchema.minItems} items`
        });
      }
      if (currentSchema.items) {
        value.forEach((item, index) => {
          validateValue(item, currentSchema.items, `${path}[${index}]`);
        });
      }
