        for (const [propName, propSchema] of Object.entries(currentSchema.properties)) {
          const propValue = value[propName];
          const propRequired = currentSchema.required?.includes(propName) ?? false;
          validateValue(propValue, propSchema, path ? `${path}.${propName}` : propName, propRequired);
